  ctx.effect(() => ctx.connection.rpc.handle(VOICE_CHANNEL, async (endpoint, payload) => {
    switch (endpoint) {
      case VOICE_ENDPOINTS.ping: {
        // 生效引擎:配置 + 模型加载结果(等待落定,不再虚报)
